import React, { useEffect, useState } from "react";
import { useParams, useHistory } from "react-router-dom";
import { Formik, Form, Field, ErrorMessage } from "formik";
import * as Yup from "yup";
import { getCarById, updateCar } from "../../services/ApiCar";

export default function UpdateVoiture() {
  const { id } = useParams();
  const history = useHistory();
  const [initialValues, setInitialValues] = useState(null);
  const [isLoading, setIsLoading] = useState(true);

  const carburantOptions = ["Essence", "Diesel", "Hybride", "Électrique", "GPL", "Bioéthanol"];
  const transmissionOptions = ["Manuelle", "Automatique", "Semi-automatique"];
  const categorieOptions = ["Economique", "Compacte", "Berline", "SUV", "Monospace", "Sportive", "Luxe"];

  const validationSchema = Yup.object().shape({
    matricule: Yup.string().required("Matricule requis"),
    model: Yup.string().required("Modèle requis"),
    marque: Yup.string().required("Marque requise"),
    prix: Yup.number().required("Prix requis").min(0),
    prix_jour: Yup.number().required("Prix/jour requis").min(0),
    NombreDeSiege: Yup.number().min(2).max(9).nullable(),
  });

  useEffect(() => {
    const fetchCar = async () => {
      try {
        const res = await getCarById(id);
        const data = res.data;
        setInitialValues({
          matricule: data.matricule || "",
          model: data.model || "",
          marque: data.marque || "",
          TypeDeCarburant: data.TypeDeCarburant || carburantOptions[0],
          Transmission: data.Transmission || transmissionOptions[0],
          Categorie: data.Categorie || categorieOptions[0],
          NombreDeSiege: data.NombreDeSiege || "",
          prix: data.prix || "",
          prix_jour: data.prix_jour || "",
          couleur: data.couleur || "",
          disponible: data.disponible || false,
        });
        setIsLoading(false);
      } catch (error) {
        console.error("Erreur:", error);
        alert("Erreur lors du chargement");
        history.push("/admin/Voiture");
      }
    };
    fetchCar();
  }, [id, history]);

  const handleSubmit = async (values) => {
    try {
      await updateCar(id, {
        ...values,
        prix: parseFloat(values.prix),
        prix_jour: parseFloat(values.prix_jour),
        NombreDeSiege: parseInt(values.NombreDeSiege),
      });
      alert("Voiture mise à jour avec succès");
      history.push("/admin/Voiture");
    } catch (error) {
      console.error("Erreur:", error);
      alert("Erreur lors de la mise à jour de la voiture");
    }
  };

  if (isLoading || !initialValues) {
    return (
      <div className="flex justify-center items-center h-64">
        <div className="animate-spin rounded-full h-12 w-12 border-t-2 border-b-2 border-blue-500"></div>
      </div>
    );
  }

  return (
    <div className="relative flex flex-col min-w-0 break-words w-full mb-6 shadow-lg rounded-lg bg-blueGray-100 border-0">
      <div className="rounded-t bg-white mb-0 px-6 py-6 flex justify-between">
        <h6 className="text-blueGray-700 text-xl font-bold">Modifier la voiture</h6>
        <button
          className="bg-lightBlue-500 text-white font-bold uppercase text-xs px-4 py-2 rounded shadow"
          onClick={() => history.push("/admin/Voiture")}
        >
          Retour
        </button>
      </div>

      <div className="flex-auto px-4 lg:px-10 py-10 pt-0">
        <Formik
          initialValues={initialValues}
          validationSchema={validationSchema}
          onSubmit={handleSubmit}
          enableReinitialize
        >
          {({ values, handleChange, setFieldValue }) => (
            <Form>
              <h6 className="text-blueGray-400 text-sm mt-3 mb-6 font-bold uppercase">
                Informations véhicule
              </h6>

              <div className="flex flex-wrap">
                <InputField name="matricule" label="Matricule*" placeholder="AA-123-BB" />
                <InputField name="model" label="Modèle*" placeholder="Clio, 208, etc." />
                <InputField name="marque" label="Marque*" placeholder="Renault, Peugeot, etc." />
                
                <SelectField name="TypeDeCarburant" label="Carburant" options={carburantOptions} />
                <SelectField name="Transmission" label="Transmission" options={transmissionOptions} />
                <SelectField name="Categorie" label="Catégorie" options={categorieOptions} />

                <InputField name="NombreDeSiege" label="Nombre de sièges" type="number" placeholder="2-9" />
              </div>

              <hr className="mt-6 border-b-1 border-blueGray-300" />
              <h6 className="text-blueGray-400 text-sm mt-3 mb-6 font-bold uppercase">Tarification</h6>

              <div className="flex flex-wrap">
                <InputField name="prix" label="Prix (€)*" type="number" placeholder="Prix d'achat" />
                <InputField name="prix_jour" label="Prix/jour (€)*" type="number" placeholder="Prix location journalière" />
                <InputField name="couleur" label="Couleur" placeholder="Couleur principale" />
              </div>

              <hr className="mt-6 border-b-1 border-blueGray-300" />
              <h6 className="text-blueGray-400 text-sm mt-3 mb-6 font-bold uppercase">Disponibilité</h6>

              <div className="mb-4 px-4">
                <label className="inline-flex items-center mt-3">
                  <input
                    type="checkbox"
                    name="disponible"
                    checked={values.disponible}
                    onChange={(e) => setFieldValue("disponible", e.target.checked)}
                    className="form-checkbox h-5 w-5 text-lightBlue-600 rounded"
                  />
                  <span className="ml-2 text-blueGray-600 font-bold uppercase text-xs">
                    Disponible immédiatement
                  </span>
                </label>
              </div>

              <div className="text-center mt-6">
                <button
                  type="submit"
                  className="bg-lightBlue-500 text-white active:bg-lightBlue-600 font-bold uppercase text-xs px-6 py-3 rounded shadow"
                >
                  Mettre à jour la voiture
                </button>
              </div>
            </Form>
          )}
        </Formik>
      </div>
    </div>
  );
}

// Composants réutilisables pour les champs :

const InputField = ({ name, label, type = "text", placeholder }) => (
  <div className="w-full lg:w-6/12 px-4">
    <div className="relative w-full mb-3">
      <label className="block uppercase text-blueGray-600 text-xs font-bold mb-2">{label}</label>
      <Field
        name={name}
        type={type}
        placeholder={placeholder}
        className="border-0 px-3 py-3 placeholder-blueGray-300 text-blueGray-600 bg-white rounded text-sm shadow w-full"
      />
      <ErrorMessage name={name} component="p" className="text-red-500 text-xs italic mt-1" />
    </div>
  </div>
);

const SelectField = ({ name, label, options }) => (
  <div className="w-full lg:w-6/12 px-4">
    <div className="relative w-full mb-3">
      <label className="block uppercase text-blueGray-600 text-xs font-bold mb-2">{label}</label>
      <Field
        as="select"
        name={name}
        className="border-0 px-3 py-3 text-blueGray-600 bg-white rounded text-sm shadow w-full"
      >
        {options.map((opt) => (
          <option key={opt} value={opt}>
            {opt}
          </option>
        ))}
      </Field>
    </div>
  </div>
);
